			}
		}
		// contractScopeActive reads valid_from with the same rule, so a start date it cannot
		// parse denies every query just as permanently — and with no valid_to, or one far
		// beyond the lookahead, the checks above never see it. A window that opens later is
		// a scheduled contract rather than a fault and stays out of this report.
		rawValidFrom := strings.TrimSpace(scope.ValidFrom)
		if rawValidFrom != "" {
			validFrom, err := time.Parse(time.RFC3339Nano, rawValidFrom)
			switch {
			case err != nil:
				report, severity = true, "high"
			// A window that closes before it opens can never serve: contractScopeActive holds
			// every query until valid_from arrives, and valid_to passes first, so the contract
			// is permanently 403. The admin write path already refuses to store one
			// (dataWorksAccessWindowOrdered), but rows written before that check are still
			// listed as active contracts, and an end beyond the lookahead leaves the valid_to
			// branches above silent. Same instant on both ends is not inverted, matching the
			// write path, which only rejects a valid_from strictly after valid_to.
			case rawValidTo != "" && validToErr == nil && validFrom.After(validTo):
				report, severity = true, "high"
			}
		}
		if !report {
			continue
		}
		summary["expiring_contracts"]++
		actions = append(actions, map[string]any{
			"type": "contract_expiring", "severity": severity, "product_key": scope.ProductKey,
			"contract_key": scope.ContractKey, "customer_key": scope.CustomerKey,
			"valid_from": scope.ValidFrom, "valid_to": scope.ValidTo,
			"next_action": "renew, narrow, or retire the customer contract scope",
		})
	}
	for _, ent := range entitlements {
		// Judge access by the same rule the runtime gate applies, not by an exact match on
		// "active". Rows written before the admin path normalised the field hold values such
		// as "Active" or " active ", which store.EntitlementActive still serves; reporting
		// those as inactive access tells the operator to revoke a grant that works.
		if !entitlementActive(ent, now) {
			summary["inactive_access"]++
			actions = append(actions, map[string]any{
				"type": "entitlement_inactive", "severity": "medium", "product_key": ent.ProductKey,
				"entitlement_id": ent.ID, "api_key_id": ent.APIKeyID, "status": ent.Status, "expires_at": ent.ExpiresAt,
				"next_action": "rotate, reactivate, or remove stale API product access",
			})
			continue
		}
		// Contracts get a lookahead warning but entitlements did not, so a customer key lost
		// product access on the expiry day with nothing on this screen beforehand.
		if entitlementExpiresWithin(ent.ExpiresAt, deadline) {
			summary["expiring_access"]++
			actions = append(actions, map[string]any{
				"type": "entitlement_expiring", "severity": "medium", "product_key": ent.ProductKey,
				"entitlement_id": ent.ID, "api_key_id": ent.APIKeyID, "contract_key": ent.ContractKey, "expires_at": ent.ExpiresAt,
				"next_action": "renew the API entitlement before the customer key loses product access",
			})
		}
	}
	for _, wm := range watermarks {
		status := strings.ToLower(strings.TrimSpace(wm.DelayStatus))
		if status == "stale" || status == "delayed" || status == "failed" {
			summary["stale_watermarks"]++
			actions = append(actions, map[string]any{
				"type": "stale_watermark", "severity": "high", "product_key": wm.ProductKey,
				"asset_key": wm.AssetKey, "delay_status": wm.DelayStatus, "data_as_of": wm.DataAsOf,
				"next_action": "refresh source data or pause proposals that depend on stale data",
			})
		}
	}
	for _, cost := range costs {
		if cost.EstimatedMargin < 0 {
			summary["negative_margin"]++
			actions = append(actions, map[string]any{
				"type": "negative_margin", "severity": "medium", "product_key": cost.ProductKey,
				"estimated_margin": cost.EstimatedMargin, "currency": cost.Currency,
				"next_action": "adjust pricing, reduce query/LLM cost, or restrict low-value usage",
			})
		}
	}
