		"product_key": product.ProductKey, "from": from.Version, "to": to.Version,
		"diff_summary": dw.DiffProductSnapshots(from.SnapshotJSON, to.SnapshotJSON),
	})
}

func (s *Server) handleDataWorksContractScopes(w http.ResponseWriter, r *http.Request, product store.DataProduct) {
	switch r.Method {
	case http.MethodGet:
		scopes, err := s.db.ListContractScopes(r.Context(), product.ProductKey, strings.TrimSpace(r.URL.Query().Get("customer_key")))
		if err != nil {
			writeOpenAIError(w, http.StatusInternalServerError, err.Error(), "server_error", "contract_scopes_failed")
			return
		}
		writeJSON(w, http.StatusOK, map[string]any{"contract_scopes": scopes})
	case http.MethodPost:
		var scope store.ContractScope
		if err := json.NewDecoder(r.Body).Decode(&scope); err != nil {
			writeOpenAIError(w, http.StatusBadRequest, "invalid JSON body", "invalid_request_error", "invalid_body")
			return
		}
		scope.ValidFrom = strings.TrimSpace(scope.ValidFrom)
		scope.ValidTo = strings.TrimSpace(scope.ValidTo)
		if !dataWorksTimestampOK(w, "valid_from", scope.ValidFrom) || !dataWorksTimestampOK(w, "valid_to", scope.ValidTo) {
			return
		}
		if !dataWorksAccessWindowOrdered(w, scope.ValidFrom, scope.ValidTo) {
			return
		}
		// A negative ceiling would read as "unlimited" at runtime, so reject it instead of
		// storing a contract that silently enforces nothing.
		if scope.RateLimit < 0 {
			writeOpenAIError(w, http.StatusBadRequest, "rate_limit must be zero (unlimited) or a positive calls-per-minute ceiling", "invalid_request_error", "invalid_rate_limit")
			return
		}
		// The runtime builds the response field list from allowed_fields alone, so a scope
		// without one answers every query with 403 (empty_contract_scope when the caller asks
		// for no field, forbidden_fields otherwise) while the admin views still list it as an
		// active contract. Reject it instead of storing a contract that can never serve data.
		scope.AllowedFields = normalizeFieldList(scope.AllowedFields)
		if len(scope.AllowedFields) == 0 {
			writeOpenAIError(w, http.StatusBadRequest, `allowed_fields must list at least one response field (use "*" for the full product schema)`, "invalid_request_error", "invalid_allowed_fields")
			return
		}
		// The runtime only masks responses for the policies applyMasking implements, so an
		// unknown value would satisfy the publish gate while every query answers unmasked.
		scope.MaskingPolicy = strings.ToLower(strings.TrimSpace(scope.MaskingPolicy))
		if !maskingPolicyKnown(scope.MaskingPolicy) {
			writeOpenAIError(w, http.StatusBadRequest, "masking_policy must be one of none, redact, hash", "invalid_request_error", "invalid_masking_policy")
			return
		}
		// Only "active" lets the runtime serve queries, so a typo such as "actve" or a synonym
		// such as "enabled" stores a contract that answers every call with 403
		// contract_scope_inactive while the admin views still list it as a customer contract.
		scope.Status = strings.ToLower(strings.TrimSpace(scope.Status))
		if !contractScopeStatusKnown(scope.Status) {
			writeOpenAIError(w, http.StatusBadRequest, "status must be one of active, draft, suspended, revoked", "invalid_request_error", "invalid_contract_status")
			return
		}
		scope.Status = firstNonEmpty(scope.Status, "active")
		scope.ContractKey = firstNonEmpty(strings.TrimSpace(scope.ContractKey), newID("scope"))
		// contract_key is chosen by the operator and is unique across the platform, not per
		// product, and the upsert rewrites product_key on conflict. Reusing a key that another
		// product already holds would therefore move that contract here, and every entitlement
		// the other product issued against it would answer 403 contract_scope_missing from the
		// next call while still listing as customer access. Refuse instead of re-parenting.
		if existing, ok, err := s.db.GetContractScope(r.Context(), scope.ContractKey); err != nil {
			writeOpenAIError(w, http.StatusInternalServerError, err.Error(), "server_error", "contract_scope_failed")
			return
		} else if ok && existing.ProductKey != product.ProductKey {
			writeOpenAIError(w, http.StatusConflict, "contract_key already belongs to product "+existing.ProductKey, "invalid_request_error", "contract_key_taken")
			return
		}
		scope.ProductKey = product.ProductKey
		scope.CreatedBy = adminID(r)
		if err := s.db.UpsertContractScope(r.Context(), scope); err != nil {
			writeOpenAIError(w, http.StatusBadRequest, err.Error(), "invalid_request_error", "contract_scope_upsert_failed")
			return
		}
		s.auditAdmin(r, "dataworks.contract_scope.upsert", "", auditJSON(map[string]any{"product_key": product.ProductKey, "contract_key": scope.ContractKey}))
		writeJSON(w, http.StatusOK, map[string]any{"ok": true, "contract_scope": scope})
	default:
		writeOpenAIError(w, http.StatusMethodNotAllowed, "method not allowed", "invalid_request_error", "method_not_allowed")
	}
}

