func bestApprovalStatus(step string, approvals []store.ApprovalTrace, now time.Time) string {
	best := "missing"
	step = strings.ToLower(strings.TrimSpace(step))
	for _, trace := range approvals {
		if strings.ToLower(strings.TrimSpace(trace.Step)) != step {
			continue
		}
		status := strings.ToLower(strings.TrimSpace(trace.Status))
		if status == "" {
			status = "pending"
		}
		// Legacy rows may carry padded timestamps because the write path did not
		// always trim them; judge on the trimmed value like store.EntitlementActive
		// and the runtime contract gate do, while leaving the stored text untouched.
		// A value that stays unreadable after trimming keeps failing closed.
		if expiresRaw := strings.TrimSpace(trace.ExpiresAt); expiresRaw != "" {
			expiresAt, err := time.Parse(time.RFC3339Nano, expiresRaw)
			if err != nil || !expiresAt.After(now) {
				status = "expired"
			}
		}
		if status == "approved" || status == "waived" {
			return status
		}
		best = status
	}
	return best
}

